//! 🌐️ Public scalar and compound clone lifecycles preserve selected grants and single output custody.
use semio_framework_test_fixtures::fixture_text;
use crate::retained_clone::*;
use crate::observe_retirement_allocations as observe;

#[test]
fn scalar_output_and_selected_close_preserve_each_lifecycle(){
 for take in [false,true]{let birth=RetainedCloneSource::<u64>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<u64>::constructor_copy_bytes(),maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..Default::default()};let(result,heap)=observe(||RetainedCloneSource::admit_owned(42u64,(),g));let(mut source,p)=result.map_err(|(e,..)|e).unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let(mut allocated,mut released)=heap;let original=source.borrow().get()as *const u64;let mut cursor=u64::retained_clone_cursor();for _ in 0..4{if cursor.output_ready(){break;}let d=cursor.advance_demands(source.borrow(),8).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=observe(||cursor.advance(source.borrow(),8,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=heap.0;released+=heap.1;}assert!(cursor.output_ready());if take{assert_eq!(cursor.take(),Some(42));}cursor.begin_close();assert!(!cursor.output_ready());assert!(cursor.take().is_none());let mut turns=0;while !cursor.terminal_is_empty(){let d=cursor.close_demands(4096).unwrap();assert_eq!(clone_cursor_close_demand::<u64>(&cursor,4096).unwrap(),d);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(cursor.close_demands(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=heap.0;released+=heap.1;turns+=1;assert!(turns<64,"scalar selected close failed to settle: {d:?}");}assert_eq!(source.borrow().get()as *const u64,original);assert_eq!(observe(||drop(cursor)).1,(0,0));while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(source.next_close_demand(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=heap.0;released+=heap.1;turns+=1;assert!(turns<128,"scalar source selected close failed to settle: {d:?}");}assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(allocated,released);}
}

#[test]
fn scalar_compounds_preserve_selected_close_and_single_output_custody(){
 fn check<T:RetainedClone+Clone+PartialEq+std::fmt::Debug+serde::Serialize>(original:T){for taken in [false,true]{let expected=original.clone();let payload=original.clone();let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let issued=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..Default::default()};let(mut source,_)=RetainedCloneSource::admit_owned(payload,(),issued).map_err(|(e,..)|e).unwrap();let mut cursor=T::retained_clone_cursor();let mut turns=0;while !cursor.output_ready(){let d=cursor.advance_demands(source.borrow(),4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=observe(||cursor.advance(source.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<128);}if taken{let output=cursor.take().unwrap();assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(&expected).unwrap());assert_eq!(output,expected);drop(output);}cursor.begin_close();assert!(!cursor.output_ready());assert!(cursor.take().is_none());while !cursor.terminal_is_empty(){let d=cursor.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(cursor.close_demands(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<512,"compound selected close did not settle: {d:?}");}assert_eq!(observe(||drop(cursor)).1,(0,0));while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(source.next_close_demand(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<1024);}assert_eq!(observe(||drop(source)).1,(0,0));}}
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../🧬️retained-clone/🧮️scalar/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for kind in law["compounds"].as_array().unwrap(){match kind.as_str().unwrap(){"scalar-vector"=>check(vec![0u64,42,u64::MAX]),"owned-vector"=>check(vec![String::from("α"),String::new()]),"optional-scalar"=>check(Some(42u64)),"optional-vector"=>check(Some(vec![0u8,42,255])),"empty-option"=>check(Option::<u64>::None),"boxed-scalar"=>check(Box::new(42u64)),"boxed-owned"=>check(Box::new(String::from("α"))),"tuple"=>check((String::from("α"),42u64)),_=>panic!("closed compound fixture kind")}}
}

#[test]
fn composite_close_quotes_its_own_child_start_before_the_child_close_protocol(){
 static STRICT_ADVANCES:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
 struct StrictAtom;struct StrictCursor{closing:bool}
 impl crate::retirement::RetireOwned for StrictAtom{fn retirement(self)->Box<dyn crate::retirement::RetirementCursor>{crate::retirement::RetireOwned::retirement(())}fn retirement_birth_bytes(&self)->Option<usize>{<()as crate::retirement::RetireOwned>::retirement_birth_bytes(&())}fn controlled_retirement_supported()->bool{true}}
 impl RetainedClone for StrictAtom{type Cursor=StrictCursor;fn retained_clone_cursor()->StrictCursor{StrictCursor{closing:false}}}
 impl RetainedCloneCursor<StrictAtom> for StrictCursor{fn advance_demands(&self,_:RetainedCloneRef<'_,StrictAtom>,_:usize)->Result<crate::RetirementDemand,crate::ValueError>{assert!(!self.closing);Ok(crate::RetirementDemand{depth:1,..Default::default()})}fn advance(&mut self,_:RetainedCloneRef<'_,StrictAtom>,_:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,crate::ValueError>{assert!(!self.closing);let items=usize::from(g.maximum_items>0&&g.maximum_depth>0);if items>0{STRICT_ADVANCES.fetch_add(1,std::sync::atomic::Ordering::SeqCst);}Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:items,..Default::default()}))}fn take(&mut self)->Option<StrictAtom>{None}fn begin_close(&mut self)->bool{let first=!self.closing;self.closing=true;first}fn terminal_is_empty(&self)->bool{self.closing}fn next_close_depth_demand(&self)->Result<usize,crate::ValueError>{Ok(usize::from(self.closing))}fn close_demands(&self,_:usize)->Result<crate::RetirementDemand,crate::ValueError>{assert!(self.closing,"parent queried an unstarted close protocol");Ok(crate::RetirementDemand{depth:1,..Default::default()})}fn close_step(&mut self,_:RetainedCloneGrant)->Result<RetainedCloneStep,crate::ValueError>{assert!(self.closing);Ok(RetainedCloneStep::Complete(Default::default()))}}
 fn close<T:RetainedClone>(mut cursor:impl RetainedCloneCursor<T>){cursor.begin_close();let d=cursor.close_demands(4096).unwrap();assert_eq!(d,crate::RetirementDemand{depth:1,..Default::default()});assert_eq!(cursor.close_step(RetainedCloneGrant{maximum_items:0,maximum_depth:1,..Default::default()}).unwrap().progress(),Default::default());let mut work=crate::work::Work::for_rows(1);while !cursor.terminal_is_empty(){let d=cursor.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(cursor.close_demands(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));work.observe(step.progress()==RetainedCloneProgress::default()&&!cursor.terminal_is_empty()&&cursor.close_demands(4096).unwrap()==d);}}
 fn inspect<T:RetainedClone>(value:T,mut cursor:impl RetainedCloneCursor<T>){let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..Default::default()};let(mut source,_)=RetainedCloneSource::admit_owned(value,(),g).map_err(|(e,..)|e).unwrap();let before=STRICT_ADVANCES.load(std::sync::atomic::Ordering::SeqCst);let mut work=crate::work::Work::for_rows(1);while STRICT_ADVANCES.load(std::sync::atomic::Ordering::SeqCst)==before{let d=cursor.advance_demands(source.borrow(),4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=observe(||cursor.advance(source.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));work.observe(step.progress()==RetainedCloneProgress::default()&&cursor.advance_demands(source.borrow(),4096).unwrap()==d);}cursor.begin_close();assert!(cursor.advance_demands(source.borrow(),4096).is_err());close::<T>(cursor);for _ in 0..128{if source.terminal_is_empty(){break;}let d=source.next_close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(source.next_close_demand(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(source.terminal_is_empty());}
 inspect(vec![StrictAtom],Vec::<StrictAtom>::retained_clone_cursor());inspect(Some(StrictAtom),Option::<StrictAtom>::retained_clone_cursor());inspect(Box::new(StrictAtom),Box::<StrictAtom>::retained_clone_cursor());inspect((StrictAtom,StrictAtom),<(StrictAtom,StrictAtom)>::retained_clone_cursor());inspect(StrictAtom,RetainedFieldCursor::<StrictAtom>::default());let mut paged=crate::retirement_queue::list::PagedList::<StrictAtom,1>::default();while !paged.has_reserved_slot(){let bytes=paged.next_allocation_bytes().unwrap();assert!(paged.reserve_one(bytes).unwrap().progressed);}paged.push_reserved(StrictAtom).unwrap_or_else(|_|panic!("strict child fixture placement"));inspect(paged,<crate::retirement_queue::list::PagedList<StrictAtom,1>>::retained_clone_cursor());
}

#[test]
fn borrow_authority_handback_selects_one_event_and_preserves_original_custody(){
 let policy:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../🧬️retained-clone/🧬️contract/🧪️tests/♻️close/🎯️dispatch/🧫️fixtures/🔣️.json")).unwrap();
 let grant=|d:crate::RetirementDemand|RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};
 for body in policy["bodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;let(original,heap)=observe(||String::from("original handback 🎟️"));let pointer=original.as_ptr();let original_bytes=heap.0;let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneBorrowAuthority::<String>::constructor_copy_bytes(),maximum_capacity_bytes:RetainedCloneBorrowAuthority::<String>::constructor_capacity_bytes(),maximum_depth:1,..Default::default()};let(admitted,heap)=observe(||RetainedCloneBorrowAuthority::admit(original,g));let(mut authority,p)=admitted.map_err(|(e,_)|e).unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let(mut born,mut freed)=(original_bytes+heap.0,heap.1);let mut alias=None;let reference=authority.borrow(1,|value|value);reference.bind(&mut alias,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}).unwrap();assert_eq!(reference.get().as_ptr(),pointer);
 for turn in 0..policy["maximumTurns"].as_u64().unwrap(){if alias.is_none(){break;}let d=RetainedCloneBinding::close_demand(&alias,body).unwrap();let g=grant(d);assert_eq!(RetainedCloneBinding::close_demand(&alias,g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||RetainedCloneBinding::close_one(&mut alias,g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;assert!(turn+1<policy["maximumTurns"].as_u64().unwrap()||alias.is_none());}assert!(alias.is_none());
 let mut output=None;for turn in 0..policy["maximumTurns"].as_u64().unwrap(){let d=authority.next_take_demands(body).unwrap();let g=grant(d);assert_eq!(authority.next_take_demands(g.maximum_copy_bytes).unwrap(),d);let denied=[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})];for denied in denied.into_iter().flatten(){let(result,heap)=observe(||authority.take_authority(denied));assert_eq!(heap,(0,0));match result{Ok(RetainedCloneSourceTake::Pending(p))=>assert_eq!(p,Default::default()),Err(_)=>{},Ok(RetainedCloneSourceTake::Ready(..))=>panic!("underfunded authority transfer")};assert_eq!(authority.next_take_demands(body).unwrap(),d);}
 let(result,heap)=observe(||authority.take_authority(g).unwrap());let p=match result{RetainedCloneSourceTake::Pending(p)=>p,RetainedCloneSourceTake::Ready(value,p)=>{assert_eq!(value.as_ptr(),pointer);assert_eq!(value,"original handback 🎟️");output=Some(value);p}};assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;if output.is_some(){break;}assert!(turn+1<policy["maximumTurns"].as_u64().unwrap(),"selected authority handback must terminate: {d:?}");}assert!(authority.terminal_is_empty());let(result,heap)=observe(||crate::retirement::controlled::ControlledRetirement::new(output.unwrap()));let mut owner=result.map_err(|(e,_)|e).unwrap();born+=heap.0;freed+=heap.1;for turn in 0..policy["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let d=owner.selected_demand(body).unwrap();let g=grant(d);assert_eq!(owner.selected_demand(g.maximum_copy_bytes).unwrap(),d);let(step,heap)=observe(||owner.step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;assert!(turn+1<policy["maximumTurns"].as_u64().unwrap()||owner.terminal_is_empty());}assert!(owner.terminal_is_empty());assert_eq!(observe(||{drop(owner);drop(authority)}).1,(0,0));assert_eq!(born,freed);}
}
